function PanelView({panel,onAction}:{panel:Panel;onAction:(msg:string)=>void}){
 return <section className={styles.panel} style={{gridColumn:`span ${panel.span}`}}><header><h2><i>{panel.kind==="table"?"▦":panel.kind==="flow"?"◉":panel.kind==="trend"?"⌁":"◇"}</i>{panel.title}</h2><button type="button" onClick={()=>onAction("Preview only: no operational record or marketing data was changed.")}>View</button></header>
 {panel.kind==="table"&&<div className={styles.table}><table><thead><tr>{(panel.columns||[]).map(c=><th key={c}>{c}</th>)}</tr></thead><tbody>{panel.rows.map((row,i)=><tr key={`${i}-${row[0]}`}>{row.map((v,j)=><td key={`${i}-${j}`}>{j===row.length-1?<b className={styles.badge}>{v}</b>:v}</td>)}</tr>)}</tbody></table></div>}
 {panel.kind==="list"&&<div className={styles.list}>{panel.rows.map((row,i)=><button type="button" key={`${i}-${row[0]}`} onClick={()=>onAction("Selected illustrative record.")}><i>{String(i+1).padStart(2,"0")}</i><b>{row[0]}</b><span>{row.slice(1).join(" · ")}</span></button>)}</div>}
 {panel.kind==="detail"&&<div className={styles.detail}>{panel.rows.map(row=><div key={row[0]}><b>{row[0]}</b><span>{row[1]}</span></div>)}</div>}
 {panel.kind==="bars"&&<div className={styles.bars}>{panel.rows.map((row,i)=><div key={row[0]}><span>{row[0]}</span><i><b style={{width:`${parseInt(row[1],10)||24+i*14}%`}}/></i><strong>{row[1]}</strong></div>)}</div>}
 {panel.kind==="flow"&&<div className={styles.flow}>{panel.rows.map((row,i)=><div key={row[0]}><i>{i+1}</i><b>{row[0]}</b><small>{row[1]}</small></div>)}</div>}
 {panel.kind==="trend"&&<div className={styles.trend}><svg viewBox="0 0 460 140" role="img" aria-label="Illustrative trend chart"><path d="M10 125H450M10 90H450M10 55H450M10 20H450" stroke="#e7edf5"/><polyline points="10,100 55,82 100,88 145,65 190,76 235,48 280,61 325,33 370,45 415,22 450,30" fill="none" stroke="#1768e8" strokeWidth="3"/><polyline points="10,120 55,111 100,104 145,108 190,91 235,97 280,84 325,89 370,69 415,76 450,60" fill="none" stroke="#13a274" strokeWidth="2"/></svg><div>{panel.rows.map(row=><span key={row[0]}><i/>{row[0]} <b>{row[1]}</b></span>)}</div></div>}
 {panel.kind==="funnel"&&<div className={styles.funnel}>{panel.rows.map((row,i)=><div key={row[0]} style={{width:`${100-i*11}%`}}><b>{row[0]}</b><strong>{row[1]}</strong></div>)}</div>}
 {panel.kind==="donut"&&<div className={styles.donut}><div><strong>78%</strong><small>Sample</small></div><ul>{panel.rows.map(row=><li key={row[0]}>{row[0]} <b>{row[1]}</b></li>)}</ul></div>}
 {panel.kind==="tiles"&&<div className={styles.flow}>{panel.rows.map((row,i)=><div key={row[0]}><i>{i+1}</i><b>{row[0]}</b><small>{row[1]}</small></div>)}</div>}
 </section>;
}

export function Phase09OperationsReference({screen,local=false}:{screen:string;local?:boolean}){
 const view=views.find(item=>item.id.toLowerCase()===screen.toLowerCase());const[tab,setTab]=useState(0);const[toast,setToast]=useState("");
 if(!view)return <p>Choose a Phase 09 or owner centre design reference.</p>;
 const owner=view.id.startsWith("O");const nav=owner?navOwner:navMarketing;
 return <div className={`phase09-operations-reference ${styles.workspace}`}><aside className={styles.sidebar}><Link href="/" className={styles.brand}><i>✚</i><span>Rudra Health OS<small>Rudra Health Care Centre</small></span></Link><nav>{nav.map((label,i)=><div key={label} className={(owner?label==="Owner Command Centre":label==="Social Media & Marketing")?styles.active:""}><i>{["⌂","♙","▦","⌂","▣","⇄","▤","₹","♙","♧","◉","▧","✓","◴","⚙","♙","◈"][i]}</i>{label}</div>)}</nav><footer><b>● Centre Online</b><small>{owner?"Organisation view · sample":"Pune Centre · marketing preview"}<br/>Synthetic data only</small><button type="button" onClick={()=>setToast("This design preview has no live synchronization.")}>↻ Preview status</button></footer></aside>
 <main className={styles.main}><header className={styles.top}><button type="button" onClick={()=>setToast("Use the preview tabs and module links to navigate.")}>☰</button><label>⌖ &nbsp; {owner?"Organisation / Centre":"Pune – Kothrud (PUN-001)"}<small>{owner?"All Centres · synthetic":"Centre / Branch · sample scope"}</small></label><input aria-label="Search preview records" placeholder="Search campaigns, content, platforms, metrics, reports, centres…"/><button type="button" onClick={()=>setToast("No live notifications in this preview.")}>♧ <sup>0</sup></button><b>{owner?"Vaishnav Sawant":"Sneha Patil"}<small>{owner?"Owner / Super Admin · Preview":"Marketing Analytics Manager · Preview"}</small></b></header>
 <div className={styles.content}><nav className={styles.screenNav} aria-label="Phase 09 and operations screens">{views.map(item=><Link key={item.id} className={item.id===view.id?styles.current:""} aria-current={item.id===view.id?"page":undefined} href={`${local?"/design-preview/operations/":owner?"/owner/design/":"/marketing/design/"}${item.id.toLowerCase()}`}><b>{item.id}</b><span>{item.title}</span></Link>)}</nav><div className={styles.notice}><b>SYNTHETIC PREVIEW · NO LIVE ACTIONS</b><span>All people, centre activity, budgets, reports, campaign metrics and operations here are illustrative samples. No patient records are exposed and no actions write to Rudra systems.</span></div>
 <div className={styles.heading}><div><small>{view.id} · {owner?"PHASE 10 · OWNER / OPERATIONS":"PHASE 09 · SOCIAL MEDIA & DIGITAL MARKETING"}</small><h1>{view.title}</h1><p>{view.subtitle}</p></div><div><button type="button" onClick={()=>setToast("Nothing was exported, changed, scheduled or sent.")}>Preview actions</button><button className={styles.primary} type="button" onClick={()=>setToast("This action is disabled in the synthetic design preview.")}>＋ &nbsp; {owner?"New Request":"View Analytics"}</button></div></div>
 {view.filters&&<div className={styles.filters}>{view.filters.map(item=><button key={item} type="button" onClick={()=>setToast(`${item} · sample filter only.`)}>{item}⌄</button>)}</div>}
 <div className={styles.stats}>{view.stats.map(row=><article key={row[1]}><i>◉</i><div><strong>{row[0]}</strong><b>{row[1]}</b><small>{row[2]}</small></div></article>)}</div><div className={styles.tabs} role="tablist">{view.tabs.map((item,i)=><button key={item} role="tab" aria-selected={tab===i} className={tab===i?styles.selected:""} type="button" onClick={()=>{setTab(i);setToast(`${item} selected · preview only.`)}}>{item}</button>)}</div>
 <div className={styles.grid}>{view.panels.map(panel=><PanelView key={panel.title} panel={panel} onAction={setToast}/>)}</div><div className={styles.bottom}><span>Rudra Health OS · {view.id} · synthetic design reference</span><Link href="/marketing/design/m012">Marketing M012 Analytics</Link><Link href="/owner">Open protected owner workspace</Link><span>Example data only · no production actions.</span></div></div></main>{toast&&<div className={styles.toast} role="status">{toast}<button type="button" onClick={()=>setToast("")}>Dismiss</button></div>}</div>;
}
